import test from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
test('existing help remains stable', () => { const r=spawnSync(process.execPath,['cli.mjs','help'],{encoding:'utf8'}); assert.equal(r.status,0); assert.equal(r.stdout,'record-report: validate <file> | summarize <file>\n'); });
{
  "private": true,
  "type": "module",
  "scripts": {
    "test": "node --test test.mjs"
  }
}

