/bin/bash -lc "rtk proxy python3 - <<'PY'
from pathlib import Path
p=Path('test.mjs')
s=p.read_text()
s += r\"\"\"
import { mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { join } from 'node:path';

function runCommand(...args) {
  return spawnSync(process.execPath, ['cli.mjs', ...args], { encoding: 'utf8' });
}

function withInput(contents, check) {
  const dir = mkdtempSync(join(process.cwd(), '.record-test-'));
  try {
    const file = join(dir, 'input');
    writeFileSync(file, contents);
    return check(file);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

const invalidRecords = [
  ['missing comma', 'a1'], ['extra comma', 'a,1,2'],
  ['empty id', ',1'], ['empty amount', 'a,'],
  ['id space', ' a,1'], ['amount space', 'a,1 '],
  ['non ASCII id', 'é,1'], ['plus', 'a,+1'], ['negative', 'a,-1'],
  ['fraction', 'a,1.5'], ['exponent', 'a,1e2'],
  ['non ASCII digit', 'a,١'], ['suffix', 'a,1x'],
  ['unsafe integer', 'a,9007199254740992'],
  ['duplicate id', 'a,1\\nb,2\\na,3'], ['CRLF', 'a,1\\r\\n'],
  ['internal blank', 'a,1\\n\\nb,2'], ['extra terminal LF', 'a,1\\n\\n'],
  ['blank row', '\\n'], ['invalid tail', 'a,1\\nb,no'],
  ['BOM', '\\uFEFFa,1'], ['line separator suffix', 'a,1\\u2028'],
];

test('validate accepts complete records', () => {
  const input = 'a,0\\nZ_9-,00012\\nx,9007199254740991';
  const expected = [{ id: 'a', amount: 0 }, { id: 'Z_9-', amount: 12 },
    { id: 'x', amount: Number.MAX_SAFE_INTEGER }];
  for (const ending of ['', '\\n']) withInput(input + ending, file => {
    const result = runCommand('validate', file);
    assert.equal(result.status, 0);
    assert.equal(result.stderr, '');
    assert.deepEqual(JSON.parse(result.stdout), expected);
  });
});

test('validate accepts empty input', () => withInput('', file => {
  const result = runCommand('validate', file);
  assert.equal(result.status, 0);
  assert.equal(result.stderr, '');
  assert.deepEqual(JSON.parse(result.stdout), []);
}));

test('parser rejects invalid records', async t => {
  const { parseRecords } = await import('./records.mjs');
  for (const [name, input] of invalidRecords) await t.test(name, () => {
    assert.throws(() => parseRecords(input));
  });
});

function assertInvalid(result) {
  assert.equal(result.status, 2);
  assert.equal(result.stdout, '');
  assert.equal(result.stderr, 'INVALID_INPUT\\n');
}

test('validate rejects invalid input atomically', async t => {
  for (const [name, input] of invalidRecords) await t.test(name, () =>
    withInput(input, file => assertInvalid(runCommand('validate', file))));
});

test('validate rejects invalid UTF8', () => {
  for (const input of [Buffer.from([0xff]),
    Buffer.concat([Buffer.from('a,1\\nb,'), Buffer.from([0xe2, 0x82])])]) {
    withInput(input, file => assertInvalid(runCommand('validate', file)));
  }
});

test('validate preserves exact grammar', async () => {
  const input = 'a,0001\\nA,0001\\n__proto__,0\\nconstructor,2';
  const expected = [{ id: 'a', amount: 1 }, { id: 'A', amount: 1 },
    { id: '__proto__', amount: 0 }, { id: 'constructor', amount: 2 }];
  const { parseRecords } = await import('./records.mjs');
  assert.deepEqual(parseRecords(input), expected);
  assert.deepEqual(parseRecords(''), []);
  assert.deepEqual(parseRecords('a,2'), [{ id: 'a', amount: 2 }]);
  withInput(input, file => {
    const result = runCommand('validate', file);
    assert.equal(result.status, 0);
    assert.equal(result.stderr, '');
    assert.deepEqual(JSON.parse(result.stdout), expected);
  });
});

test('help has empty stderr', () => assert.equal(runCommand('help').stderr, ''));
test('unknown command remains stable', () => {
  const result = runCommand('not-a-command');
  assert.equal(result.status, 2);
  assert.equal(result.stdout, '');
  assert.equal(result.stderr, 'UNKNOWN_COMMAND\\n');
});
\"\"\"
p.write_text(s)
PY"

